fn handle_chdir(args: &[String]) {
    let usage = "executable chdir <folder path>";

    if args.is_empty() {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <folder path>", usage);
    }
    if args.len() > 1 {
        print_unknown_arg_error_and_exit(&args[1], usage);
    }

    let info = match get_current_vault_info() {
        Ok(i) => i,
        Err(msg) => {
            print_error(msg);
            return;
        }
    };

    let target_str = &args[0];
    let raw_target = if target_str.starts_with('/') {
        PathBuf::from(target_str)
    } else {
        info.current_folder_path.join(target_str)
    };

    let norm_target = normalize_path(&raw_target);
    let norm_root = normalize_path(&info.vault_root);

    if !norm_target.starts_with(&norm_root) {
        print_error("path crosses the bounds of vault");
        return;
    }

    if !norm_target.is_dir() {
        print_error("couldn't find the path specified");
        return;
    }

    let norm_current = normalize_path(&info.current_folder_path);
    if norm_target == norm_current {
        print_error("new location is same as old location");
        return;
    }

    let rel_path = norm_target.strip_prefix(&norm_root).unwrap();
    let new_folder_str = rel_path.to_str().unwrap_or("").to_string();

    if let Ok(mut vdata) = VaultData::load(&info.vault_root) {
        vdata.folder = new_folder_str;
        vdata.save(&info.vault_root);
    }

    println!("folder changed");
}

fn handle_list(args: &[String]) {
    let usage = "executable list [item type]";

    let mut filter = None;
    if !args.is_empty() {
        if args.len() > 1 {
            print_unknown_arg_error_and_exit(&args[1], usage);
        }
        let item_type = &args[0];
        match item_type.as_str() {
            "note" | "nt" => filter = Some("note"),
            "folder" | "fd" => filter = Some("folder"),
            _ => {
                print_invalid_value_error_and_exit(
                    item_type,
                    "<item type>",
                    &["note", "nt", "folder", "fd"],
                    usage,
                );
            }
        }
    }

    let info = match get_current_vault_info() {
        Ok(i) => i,
        Err(msg) => {
            print_error(msg);
            return;
        }
    };

    if info.folder.is_empty() {
        println!("{}", info.vault_name);
    } else {
        println!("{} > {}", info.vault_name, info.folder);
    }

    match filter {
        None => {
            print_tree(&info.current_folder_path, "");
        }
        Some("note") => {
            if let Ok(entries) = fs::read_dir(&info.current_folder_path) {
                let mut notes = Vec::new();
                for entry in entries.flatten() {
                    let path = entry.path();
                    if path.is_file() {
                        if let Some(ext) = path.extension() {
                            if ext == "md" {
                                if let Some(stem) = path.file_stem() {
                                    notes.push(stem.to_string_lossy().to_string());
                                }
                            }
                        }
                    }
                }
                let total = notes.len();
                for (idx, name) in notes.iter().enumerate() {
                    let is_last = idx == total - 1;
                    let connector = if is_last { "└── " } else { "├── " };
                    println!("{}{}", connector, blue(name));
                }
            }
        }
        Some("folder") => {
            if let Ok(entries) = fs::read_dir(&info.current_folder_path) {
                let mut folders = Vec::new();
                for entry in entries.flatten() {
                    let path = entry.path();
                    if path.is_dir() {
                        if let Some(fname) = path.file_name() {
                            folders.push(fname.to_string_lossy().to_string());
                        }
                    }
                }
                let total = folders.len();
                for (idx, name) in folders.iter().enumerate() {
                    let is_last = idx == total - 1;
                    let connector = if is_last { "└── " } else { "├── " };
                    println!("{}{}", connector, name);
                }
            }
        }
        _ => {}
    }
}

fn print_tree(dir: &Path, prefix: &str) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    struct Item {
        name: String,
        is_dir: bool,
        path: PathBuf,
    }

    let mut items = Vec::new();
    for entry in entries.flatten() {
        let path = entry.path();
        let fname = match path.file_name() {
            Some(n) => n.to_string_lossy().to_string(),
            None => continue,
        };

        if fname == ".jot" {
            continue;
        }

        let is_dir = path.is_dir();
        if is_dir {
            items.push(Item { name: fname, is_dir: true, path });
        } else if path.is_file() {
            if let Some(ext) = path.extension() {
                if ext == "md" {
                    let stem = path.file_stem().unwrap().to_string_lossy().to_string();
                    items.push(Item { name: stem, is_dir: false, path });
                }
            }
        }
    }

    let total = items.len();
    for (idx, item) in items.iter().enumerate() {
        let is_last = idx == total - 1;
        let connector = if is_last { "└── " } else { "├── " };
        let display_name = if item.is_dir {
            item.name.clone()
        } else {
            blue(&item.name)
        };

        println!("{}{}{}", prefix, connector, display_name);

        if item.is_dir {
            let sub_prefix = if is_last { "    " } else { "│   " };
            let new_prefix = format!("{}{}", prefix, sub_prefix);
            print_tree(&item.path, &new_prefix);
        }
    }
}

fn handle_remove(args: &[String]) {
    let usage = "executable remove <item type> <name>";

    if args.is_empty() {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <item type>\n    <name>", usage);
    }

    let item_type = &args[0];
    let possible = ["vault", "vl", "note", "nt", "folder", "fd"];
    if !possible.contains(&item_type.as_str()) {
        print_invalid_value_error_and_exit(item_type, "<item type>", &possible, usage);
    }

    if args.len() == 1 {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <name>", usage);
    }

    if args.len() > 2 {
        print_unknown_arg_error_and_exit(&args[2], usage);
    }

    let name = &args[1];

    match item_type.as_str() {
        "vault" | "vl" => {
            let mut vf = VaultsFile::load();
            if !vf.vaults.contains_key(name) {
                print_error(&format!("vault {} doesn't exist", name));
                return;
            }

            let parent_loc = vf.vaults.remove(name).unwrap();
            let vault_path = Path::new(&parent_loc).join(name);
            if vault_path.exists() {
                let _ = fs::remove_dir_all(vault_path);
            }

            if vf.current.as_deref() == Some(name) {
                vf.current = None;
            }
            vf.save();

            println!("vault {} removed", blue(name));
        }
        "note" | "nt" => {
            let info = match get_current_vault_info() {
                Ok(i) => i,
                Err(msg) => {
                    print_error(msg);
                    return;
                }
            };

            let filename = if name.ends_with(".md") {
                name.to_string()
            } else {
                format!("{}.md", name)
            };

            let note_path = info.current_folder_path.join(&filename);
            if !note_path.is_file() {
                print_error(&format!("note {} not found", name));
                return;
            }

            let _ = fs::remove_file(note_path);
            println!("note {} removed", blue(name));
        }
        "folder" | "fd" => {
            let info = match get_current_vault_info() {
                Ok(i) => i,
                Err(msg) => {
                    print_error(msg);
                    return;
                }
            };

            let folder_path = info.current_folder_path.join(name);
            if !folder_path.is_dir() {
                print_error(&format!("folder {} not found", name));
                return;
            }

            let _ = fs::remove_dir_all(folder_path);
            println!("folder {} removed", blue(name));
        }
        _ => {}
    }
}

fn handle_rename(args: &[String]) {
    let usage = "executable rename <item type> <name> <new name>";

    if args.is_empty() {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <item type>\n    <name>\n    <new name>", usage);
    }

    let item_type = &args[0];
    let possible = ["vault", "vl", "note", "nt", "folder", "fd"];
    if !possible.contains(&item_type.as_str()) {
        print_invalid_value_error_and_exit(item_type, "<item type>", &possible, usage);
    }

    if args.len() == 1 {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <name>\n    <new name>", usage);
    }

    if args.len() == 2 {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <new name>", usage);
    }

    if args.len() > 3 {
        print_unknown_arg_error_and_exit(&args[3], usage);
    }

    let name = &args[1];
    let new_name = &args[2];

    match item_type.as_str() {
        "vault" | "vl" => {
            let mut vf = VaultsFile::load();
            if !vf.vaults.contains_key(name) {
                print_error(&format!("vault {} doesn't exist", name));
                return;
            }

            if new_name.contains('/') || new_name.contains('\\') {
                print_error("invalid name");
                return;
            }

            let parent_loc = vf.vaults.remove(name).unwrap();
            let old_vault_path = Path::new(&parent_loc).join(name);
            let new_vault_path = Path::new(&parent_loc).join(new_name);

            if old_vault_path.exists() {
                let _ = fs::rename(&old_vault_path, &new_vault_path);
                if let Ok(mut vdata) = VaultData::load(&new_vault_path) {
                    vdata.name = new_name.clone();
                    vdata.save(&new_vault_path);
                }
            }

            vf.vaults.insert(new_name.clone(), parent_loc);
            if vf.current.as_deref() == Some(name) {
                vf.current = Some(new_name.clone());
            }
            vf.save();

            println!("vault {} renamed to {}", blue(name), blue(new_name));
        }
        "note" | "nt" => {
            let info = match get_current_vault_info() {
                Ok(i) => i,
                Err(msg) => {
                    print_error(msg);
                    return;
                }
            };

            if new_name.contains('/') || new_name.contains('\\') {
                print_error("invalid name");
                return;
            }

            let old_filename = if name.ends_with(".md") {
                name.to_string()
            } else {
                format!("{}.md", name)
            };
            let new_filename = if new_name.ends_with(".md") {
                new_name.to_string()
            } else {
                format!("{}.md", new_name)
            };

            let old_path = info.current_folder_path.join(&old_filename);
            let new_path = info.current_folder_path.join(&new_filename);

            if !old_path.is_file() {
                print_error(&format!("note {} not found", name));
                return;
            }

            let _ = fs::rename(old_path, new_path);
            println!("note {} renamed to {}", blue(name), blue(new_name));
        }
        "folder" | "fd" => {
            let info = match get_current_vault_info() {
                Ok(i) => i,
                Err(msg) => {
                    print_error(msg);
                    return;
                }
            };

            if new_name.contains('/') || new_name.contains('\\') {
                print_error("invalid name");
                return;
            }

            let old_path = info.current_folder_path.join(name);
            let new_path = info.current_folder_path.join(new_name);

            if !old_path.is_dir() {
                print_error(&format!("folder {} not found", name));
                return;
            }

            let _ = fs::rename(old_path, new_path);
            println!("folder {} renamed to {}", blue(name), blue(new_name));
        }
        _ => {}
    }
}

fn handle_move(args: &[String]) {
    let usage = "executable move <item type> <name> <new location>";

    if args.is_empty() {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <item type>\n    <name>\n    <new location>", usage);
    }

    let item_type = &args[0];
    let possible = ["vault", "vl", "note", "nt", "folder", "fd"];
    if !possible.contains(&item_type.as_str()) {
        print_invalid_value_error_and_exit(item_type, "<item type>", &possible, usage);
    }

    if args.len() == 1 {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <name>\n    <new location>", usage);
    }

    if args.len() == 2 {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <new location>", usage);
    }

    if args.len() > 3 {
        print_unknown_arg_error_and_exit(&args[3], usage);
    }

    let name = &args[1];
    let new_loc_raw = &args[2];

    match item_type.as_str() {
        "vault" | "vl" => {
            let mut vf = VaultsFile::load();
            if !vf.vaults.contains_key(name) {
                print_error(&format!("vault {} doesn't exist", name));
                return;
            }

            if !new_loc_raw.starts_with('/') {
                print_error("specified path isn't absolute");
                return;
            }

            let new_loc_path = Path::new(new_loc_raw);
            if !new_loc_path.exists() {
                print_error("couldn't find the path specified");
                return;
            }

            let old_loc = vf.vaults.get(name).unwrap().clone();
            let old_vault_path = Path::new(&old_loc).join(name);
            let clean_new_loc = new_loc_raw.trim_end_matches('/').to_string();
            let new_vault_path = Path::new(&clean_new_loc).join(name);

            if old_vault_path == new_vault_path {
                print_error("new location is same as old location");
                return;
            }

            let _ = fs::rename(&old_vault_path, &new_vault_path);
            if let Ok(mut vdata) = VaultData::load(&new_vault_path) {
                vdata.location = clean_new_loc.clone();
                vdata.save(&new_vault_path);
            }

            vf.vaults.insert(name.clone(), clean_new_loc);
            vf.save();

            println!("vault {} moved", blue(name));
        }
        "note" | "nt" => {
            let info = match get_current_vault_info() {
                Ok(i) => i,
                Err(msg) => {
                    print_error(msg);
                    return;
                }
            };

            let filename = if name.ends_with(".md") {
                name.to_string()
            } else {
                format!("{}.md", name)
            };

            let old_path = info.current_folder_path.join(&filename);

            let raw_dest = if new_loc_raw.starts_with('/') {
                PathBuf::from(new_loc_raw)
            } else {
                info.current_folder_path.join(new_loc_raw)
            };

            let norm_dest = normalize_path(&raw_dest);
            let norm_root = normalize_path(&info.vault_root);

            if !norm_dest.starts_with(&norm_root) {
                print_error("path crosses the bounds of vault");
                return;
            }

            if !norm_dest.is_dir() {
                print_error("couldn't find the path specified");
                return;
            }

            let target_path = norm_dest.join(&filename);

            let norm_old = normalize_path(&old_path);
            let norm_target = normalize_path(&target_path);

            if norm_old == norm_target {
                print_error("new location is same as old location");
                return;
            }

            if norm_target.exists() {
                print_error(&format!("a note named {} already exists in this location", name));
                return;
            }

            if !old_path.is_file() {
                print_error(&format!("note {} not found", name));
                return;
            }

            let _ = fs::rename(old_path, target_path);
            println!("note {} moved", blue(name));
        }
        "folder" | "fd" => {
            let info = match get_current_vault_info() {
                Ok(i) => i,
                Err(msg) => {
                    print_error(msg);
                    return;
                }
            };

            let old_path = info.current_folder_path.join(name);

            let raw_dest = if new_loc_raw.starts_with('/') {
                PathBuf::from(new_loc_raw)
            } else {
                info.current_folder_path.join(new_loc_raw)
            };

            let norm_dest = normalize_path(&raw_dest);
            let norm_root = normalize_path(&info.vault_root);

            if !norm_dest.starts_with(&norm_root) {
                print_error("path crosses the bounds of vault");
                return;
            }

            if !norm_dest.is_dir() {
                print_error("couldn't find the path specified");
                return;
            }

            let target_path = norm_dest.join(name);

            let norm_old = normalize_path(&old_path);
            let norm_target = normalize_path(&target_path);

            if norm_old == norm_target {
                print_error("new location is same as old location");
                return;
            }

            if !old_path.is_dir() {
                print_error(&format!("folder {} not found", name));
                return;
            }

            let _ = fs::rename(old_path, target_path);
            println!("folder {} moved", blue(name));
        }
        _ => {}
    }
}

fn handle_vmove(args: &[String]) {
    let usage = "executable vmove <item type> <name> <vault name>";

    if args.is_empty() {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <item type>\n    <name>\n    <vault name>", usage);
    }

    let item_type = &args[0];
    let possible = ["note", "nt", "folder", "fd"];
    if !possible.contains(&item_type.as_str()) {
        print_invalid_value_error_and_exit(item_type, "<item type>", &possible, usage);
    }

    if args.len() == 1 {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <name>\n    <vault name>", usage);
    }

    if args.len() == 2 {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <vault name>", usage);
    }

    if args.len() > 3 {
        print_unknown_arg_error_and_exit(&args[3], usage);
    }

    let name = &args[1];
    let target_vault_name = &args[2];

    let vf = VaultsFile::load();
    if !vf.vaults.contains_key(target_vault_name) {
        // Bug replication in original tool: formats `name` instead of `target_vault_name` in error string
        print_error(&format!("vault {} doesn't exist", name));
        return;
    }

    let info = match get_current_vault_info() {
        Ok(i) => i,
        Err(msg) => {
            print_error(msg);
            return;
        }
    };

    if info.vault_name == *target_vault_name {
        let display_type = if item_type == "note" || item_type == "nt" { "note" } else { "folder" };
        println!("{} {} already exists in vault {}", display_type, name, target_vault_name);
        print_error("new location is same as old location");
        return;
    }

    let target_vault_parent = vf.vaults.get(target_vault_name).unwrap();
    let target_vault_root = Path::new(target_vault_parent).join(target_vault_name);

    match item_type.as_str() {
        "note" | "nt" => {
            let filename = if name.ends_with(".md") {
                name.to_string()
            } else {
                format!("{}.md", name)
            };

            let old_path = info.current_folder_path.join(&filename);
            let target_path = target_vault_root.join(&filename);

            if target_path.exists() {
                print_error(&format!("a note named {} already exists in this location", name));
                return;
            }

            if !old_path.is_file() {
                print_error(&format!("note {} not found", name));
                return;
            }

            let _ = fs::rename(old_path, target_path);
            println!("note {} moved to vault {}", blue(name), blue(target_vault_name));
        }
        "folder" | "fd" => {
            let old_path = info.current_folder_path.join(name);
            let target_path = target_vault_root.join(name);

            if target_path.exists() {
                print_error(&format!("a folder named {} already exists in this location", name));
                return;
            }

            if !old_path.is_dir() {
                print_error(&format!("folder {} not found", name));
                return;
            }

            let _ = fs::rename(old_path, target_path);
            println!("folder {} moved to vault {}", blue(name), blue(target_vault_name));
        }
        _ => {}
    }
}

fn handle_config(args: &[String]) {
    let usage = "jt config <config type>\n    jt config <config type> [config value]";

    if args.is_empty() {
        let cfg = Config::load();
        let editor = match cfg.editor {
            Some(e) if !e.is_empty() => e,
            _ => {
                print_error("editor not found");
                return;
            }
        };

        let config_file = get_config_dir().join("config");
        if Command::new(&editor).arg(&config_file).status().is_err() {
            print_error("editor not found");
        }
        return;
    }

    let config_type = &args[0];
    let possible = ["editor", "conflict"];
    if !possible.contains(&config_type.as_str()) {
        print_invalid_value_error_and_exit(config_type, "<config type>", &possible, usage);
    }

    if args.len() == 1 {
        let cfg = Config::load();
        match config_type.as_str() {
            "editor" => {
                if let Some(ref ed) = cfg.editor {
                    println!("editor: {}", blue(ed));
                }
            }
            "conflict" => {
                println!("conflict: {}", blue(if cfg.conflict { "true" } else { "false" }));
            }
            _ => {}
        }
        return;
    }

    if args.len() > 2 {
        print_unknown_arg_error_and_exit(&args[2], usage);
    }

    let val = &args[1];
    let mut cfg = Config::load();

    match config_type.as_str() {
        "editor" => {
            cfg.editor = Some(val.clone());
            cfg.save();
            println!("set {} to {}", blue("editor"), blue(val));
        }
        "conflict" => {
            if val == "true" || val == "false" {
                cfg.conflict = val == "true";
                cfg.save();
                println!("set {} to {}", blue("conflict"), blue(val));
            }
        }
        _ => {}
    }
}
