fn get_config_dir() -> PathBuf {
    if let Ok(val) = env::var("XDG_CONFIG_HOME") {
        if !val.is_empty() {
            return PathBuf::from(val).join("jot");
        }
    }
    let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
    PathBuf::from(home).join(".config").join("jot")
}

fn get_data_dir() -> PathBuf {
    if let Ok(val) = env::var("XDG_DATA_HOME") {
        if !val.is_empty() {
            return PathBuf::from(val).join("jot");
        }
    }
    let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
    PathBuf::from(home).join(".local").join("share").join("jot")
}

struct Config {
    editor: Option<String>,
    conflict: bool,
}

impl Config {
    fn load() -> Config {
        let config_path = get_config_dir().join("config");
        let mut editor = Some("nvim".to_string());
        let mut conflict = true;

        if config_path.exists() {
            if let Ok(content) = fs::read_to_string(&config_path) {
                for line in content.lines() {
                    let line = line.trim();
                    if line.starts_with("editor") {
                        if let Some((_, val)) = line.split_once('=') {
                            let val = val.trim().trim_matches('\'').trim_matches('"');
                            editor = Some(val.to_string());
                        }
                    } else if line.starts_with("conflict") {
                        if let Some((_, val)) = line.split_once('=') {
                            let val = val.trim();
                            if val == "true" {
                                conflict = true;
                            } else if val == "false" {
                                conflict = false;
                            }
                        }
                    }
                }
            }
        } else {
            let _ = fs::create_dir_all(get_config_dir());
            let default_content = "editor = 'nvim'\nconflict = true\n";
            let _ = fs::write(&config_path, default_content);
        }

        Config { editor, conflict }
    }

    fn save(&self) {
        let _ = fs::create_dir_all(get_config_dir());
        let config_path = get_config_dir().join("config");
        let mut content = String::new();
        if let Some(ref ed) = self.editor {
            content.push_str(&format!("editor = '{}'\n", ed));
        }
        content.push_str(&format!("conflict = {}\n", if self.conflict { "true" } else { "false" }));
        let _ = fs::write(config_path, content);
    }
}

struct VaultsFile {
    current: Option<String>,
    vaults: BTreeMap<String, String>,
}

impl VaultsFile {
    fn load() -> VaultsFile {
        let vaults_path = get_data_dir().join("vaults");
        let mut current = None;
        let mut vaults = BTreeMap::new();

        if vaults_path.exists() {
            if let Ok(content) = fs::read_to_string(&vaults_path) {
                let mut in_vaults_section = false;
                for line in content.lines() {
                    let line = line.trim();
                    if line.starts_with("current") {
                        if let Some((_, val)) = line.split_once('=') {
                            let val = val.trim().trim_matches('\'').trim_matches('"');
                            current = Some(val.to_string());
                        }
                    } else if line == "[vaults]" {
                        in_vaults_section = true;
                    } else if in_vaults_section && !line.is_empty() {
                        if let Some((k, v)) = line.split_once('=') {
                            let k = k.trim();
                            let v = v.trim().trim_matches('\'').trim_matches('"');
                            vaults.insert(k.to_string(), v.to_string());
                        }
                    }
                }
            }
        } else {
            let _ = fs::create_dir_all(get_data_dir());
            let default_content = "[vaults]\n";
            let _ = fs::write(&vaults_path, default_content);
        }

        VaultsFile { current, vaults }
    }

    fn save(&self) {
        let _ = fs::create_dir_all(get_data_dir());
        let vaults_path = get_data_dir().join("vaults");
        let mut content = String::new();
        if let Some(ref cur) = self.current {
            content.push_str(&format!("current = '{}'\n\n", cur));
        }
        content.push_str("[vaults]\n");
        for (k, v) in &self.vaults {
            content.push_str(&format!("{} = '{}'\n", k, v));
        }
        let _ = fs::write(vaults_path, content);
    }
}

struct VaultData {
    name: String,
    location: String,
    folder: String,
}

impl VaultData {
    fn load(vault_root: &Path) -> Result<VaultData, String> {
        let data_path = vault_root.join(".jot").join("data");
        if !data_path.exists() {
            return Err("data file not found".to_string());
        }
        let content = fs::read_to_string(&data_path).map_err(|e| e.to_string())?;
        let mut name = String::new();
        let mut location = String::new();
        let mut folder = String::new();

        for line in content.lines() {
            let line = line.trim();
            if line.starts_with("name") {
                if let Some((_, val)) = line.split_once('=') {
                    name = val.trim().trim_matches('\'').trim_matches('"').to_string();
                }
            } else if line.starts_with("location") {
                if let Some((_, val)) = line.split_once('=') {
                    location = val.trim().trim_matches('\'').trim_matches('"').to_string();
                }
            } else if line.starts_with("folder") {
                if let Some((_, val)) = line.split_once('=') {
                    folder = val.trim().trim_matches('\'').trim_matches('"').to_string();
                }
            }
        }

        Ok(VaultData {
            name,
            location,
            folder,
        })
    }

    fn save(&self, vault_root: &Path) {
        let jot_dir = vault_root.join(".jot");
        let _ = fs::create_dir_all(&jot_dir);
        let data_path = jot_dir.join("data");
        let content = format!(
            "name = '{}'\nlocation = '{}'\nfolder = '{}'\nhistory = []\n",
            self.name, self.location, self.folder
        );
        let _ = fs::write(data_path, content);
    }
}

struct CurrentVaultInfo {
    vault_name: String,
    parent_location: String,
    vault_root: PathBuf,
    folder: String,
    current_folder_path: PathBuf,
}

fn get_current_vault_info() -> Result<CurrentVaultInfo, &'static str> {
    let vf = VaultsFile::load();
    let current_name = vf.current.ok_or("not inside a vault")?;
    let parent_location = vf.vaults.get(&current_name).ok_or("not inside a vault")?;

    let vault_root = PathBuf::from(parent_location).join(&current_name);
    let vdata = VaultData::load(&vault_root).map_err(|_| "not inside a vault")?;

    let current_folder_path = if vdata.folder.is_empty() {
        vault_root.clone()
    } else {
        vault_root.join(&vdata.folder)
    };

    Ok(CurrentVaultInfo {
        vault_name: current_name,
        parent_location: parent_location.clone(),
        vault_root,
        folder: vdata.folder,
        current_folder_path,
    })
}

fn normalize_path(path: &Path) -> PathBuf {
    let mut components = Vec::new();
    for comp in path.components() {
        use std::path::Component;
        match comp {
            Component::Prefix(..) | Component::RootDir => {
                components.clear();
                components.push(comp.as_os_str());
            }
            Component::CurDir => {}
            Component::ParentDir => {
                components.pop();
            }
            Component::Normal(c) => {
                components.push(c);
            }
        }
    }
    let mut res = PathBuf::new();
    for c in components {
        res.push(c);
    }
    res
}

