fn handle_vault(args: &[String]) {
    let usage = "jt vault\n    jt vault -l\n    jt vault <vault name> <vault location>";

    if args.is_empty() {
        let vf = VaultsFile::load();
        for (k, _) in &vf.vaults {
            println!("   {}", k);
        }
        return;
    }

    if args.len() == 1 && args[0] == "-l" {
        let vf = VaultsFile::load();
        for (k, v) in &vf.vaults {
            println!("   {} \t {}", k, v);
        }
        return;
    }

    if args[0].starts_with('-') {
        print_unknown_arg_error_and_exit(&args[0], usage);
    }

    if args.len() == 1 {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <vault location>", usage);
    }

    if args.len() > 2 {
        print_unknown_arg_error_and_exit(&args[2], usage);
    }

    let vault_name = &args[0];
    let location_raw = &args[1];

    if !location_raw.starts_with('/') {
        print_error("specified path isn't absolute");
        return;
    }

    let location_path = Path::new(location_raw);
    if !location_path.exists() {
        print_error("couldn't find the path specified");
        return;
    }

    let mut vf = VaultsFile::load();
    if vf.vaults.contains_key(vault_name) {
        print_error(&format!("vault {} already exists", vault_name));
        return;
    }

    let location_clean = location_raw.trim_end_matches('/').to_string();
    let new_vault_dir = Path::new(&location_clean).join(vault_name);

    let _ = fs::create_dir_all(&new_vault_dir);

    let vdata = VaultData {
        name: vault_name.clone(),
        location: location_clean.clone(),
        folder: "".to_string(),
    };
    vdata.save(&new_vault_dir);

    vf.vaults.insert(vault_name.clone(), location_clean);
    vf.save();

    println!("vault {} created", blue(vault_name));
}

fn handle_note(args: &[String]) {
    let usage = "jt note\n    jt note [note name]";

    if args.is_empty() {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <note name>", usage);
    }
    if args.len() > 1 {
        print_unknown_arg_error_and_exit(&args[1], usage);
    }

    let note_name = &args[0];
    if note_name.contains('/') || note_name.contains('\\') {
        print_error("invalid name");
        return;
    }

    let info = match get_current_vault_info() {
        Ok(i) => i,
        Err(msg) => {
            print_error(msg);
            return;
        }
    };

    let filename = if note_name.ends_with(".md") {
        note_name.to_string()
    } else {
        format!("{}.md", note_name)
    };

    let note_path = info.current_folder_path.join(&filename);
    if note_path.exists() {
        print_error(&format!("a note named {} already exists in this location", note_name));
        return;
    }

    let _ = fs::File::create(&note_path);
    println!("note {} created", blue(note_name));
}

fn handle_folder(args: &[String]) {
    let usage = "jt folder\n    jt folder [folder name]";

    if args.is_empty() {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <folder name>", usage);
    }
    if args.len() > 1 {
        print_unknown_arg_error_and_exit(&args[1], usage);
    }

    let folder_name = &args[0];
    if folder_name.contains('/') || folder_name.contains('\\') {
        print_error("invalid name");
        return;
    }

    let info = match get_current_vault_info() {
        Ok(i) => i,
        Err(msg) => {
            print_error(msg);
            return;
        }
    };

    let folder_path = info.current_folder_path.join(folder_name);
    if folder_path.exists() {
        print_error(&format!("a folder named {} already exists in this location", folder_name));
        return;
    }

    let _ = fs::create_dir_all(&folder_path);
    println!("folder {} created", blue(folder_name));
}

fn handle_enter(args: &[String]) {
    let usage = "executable enter <vault name>";

    if args.is_empty() {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <vault name>", usage);
    }
    if args.len() > 1 {
        print_unknown_arg_error_and_exit(&args[1], usage);
    }

    let target_vault = &args[0];
    let mut vf = VaultsFile::load();

    if !vf.vaults.contains_key(target_vault) {
        print_error(&format!("vault {} doesn't exist", target_vault));
        return;
    }

    if vf.current.as_deref() == Some(target_vault) {
        print_error(&format!("already in vault {}", target_vault));
        return;
    }

    vf.current = Some(target_vault.clone());
    vf.save();

    println!("entered {}", blue(target_vault));
}

fn handle_open(args: &[String]) {
    let usage = "executable open <note name>";

    if args.is_empty() {
        print_usage_error_and_exit("The following required arguments were not provided:\n    <note name>", usage);
    }
    if args.len() > 1 {
        print_unknown_arg_error_and_exit(&args[1], usage);
    }

    let info = match get_current_vault_info() {
        Ok(i) => i,
        Err(msg) => {
