fn handle_config(args: &[String]) {
    let usage = "jt config <config type>\n    jt config <config type> [config value]";

    if args.is_empty() {
        let cfg = Config::load();
        let editor = match cfg.editor {
            Some(e) if !e.is_empty() => e,
            _ => {
                print_error("editor not found");
                return;
            }
        };

        let config_file = get_config_dir().join("config");
        if Command::new(&editor).arg(&config_file).status().is_err() {
            print_error("editor not found");
        }
        return;
    }

    let config_type = &args[0];
    let possible = ["editor", "conflict"];
    if !possible.contains(&config_type.as_str()) {
        print_invalid_value_error_and_exit(config_type, "<config type>", &possible, usage);
    }

    if args.len() == 1 {
        let cfg = Config::load();
        match config_type.as_str() {
            "editor" => {
                if let Some(ref ed) = cfg.editor {
                    println!("editor: {}", blue(ed));
                }
            }
            "conflict" => {
                println!("conflict: {}", blue(if cfg.conflict { "true" } else { "false" }));
            }
            _ => {}
        }
        return;
    }

    if args.len() > 2 {
        print_unknown_arg_error_and_exit(&args[2], usage);
    }

    let val = &args[1];
    let mut cfg = Config::load();

    match config_type.as_str() {
        "editor" => {
            cfg.editor = Some(val.clone());
            cfg.save();
            println!("set {} to {}", blue("editor"), blue(val));
        }
        "conflict" => {
            if val == "true" || val == "false" {
                cfg.conflict = val == "true";
                cfg.save();
                println!("set {} to {}", blue("conflict"), blue(val));
            }
        }
        _ => {}
    }
}
