    if args.len() > 3 {
        print_unknown_arg_error_and_exit(&args[3], usage);
    }

    let name = &args[1];
    let target_vault_name = &args[2];

    let vf = VaultsFile::load();
    if !vf.vaults.contains_key(target_vault_name) {
        // Bug replication in original tool: formats `name` instead of `target_vault_name` in error string
        print_error(&format!("vault {} doesn't exist", name));
        return;
    }

    let info = match get_current_vault_info() {
        Ok(i) => i,
        Err(msg) => {
            print_error(msg);
            return;
        }
