                return;
            }

            let old_loc = vf.vaults.get(name).unwrap().clone();
            let old_vault_path = Path::new(&old_loc).join(name);
            let clean_new_loc = new_loc_raw.trim_end_matches('/').to_string();
            let new_vault_path = Path::new(&clean_new_loc).join(name);

            if old_vault_path == new_vault_path {
                print_error("new location is same as old location");
